  $('campus-search-form').onsubmit=async e=>{e.preventDefault();const generation=++campusGeneration;try{const result=await api(opUrl('/search',{q:$('campus-search-query').value}));if(generation!==campusGeneration||section!=='home')return;$('campus-search-coverage').textContent=result.coverage;$('campus-search-results').innerHTML=result.items.map(row=>`<article class="campus-result"><span class="badge">${esc(row.kind)}</span><h3><a href="${esc(transport.href(row.source_url))}">${esc(row.title)}</a></h3><p>${esc(row.excerpt||'')}</p><p class="caption">${esc(row.status||'')} ${esc(row.location||'')}</p></article>`).join('')||'<p class="ops-empty">No currently authorized matching records.</p>';}catch(error){if(generation===campusGeneration){$('campus-search-results').replaceChildren();message(error.message,true);}}};
  async function loadRequester(){const generation=++requesterGeneration;try{const result=await api(opUrl('/requester'));if(generation!==requesterGeneration||section!=='requester')return;$('requester-department').innerHTML=result.departments.map(row=>`<option value="${esc(row.id)}">${esc(row.name)}</option>`).join('');$('requester-submit').disabled=!result.departments.length||requesterBusy;$('requester-coverage').textContent=result.coverage;$('requester-list').innerHTML=result.requests.map(row=>`<article><span class="badge">${esc(row.status)}</span><h3><button class="link" data-requester-id="${esc(row.id)}">${esc(row.title)}</button></h3><p class="caption">${esc(row.updated_at||'')}</p></article>`).join('')||'<p>No submitted requests yet.</p>';$('requester-list').querySelectorAll('[data-requester-id]').forEach(button=>button.onclick=()=>showRequester(button.dataset.requesterId));const draft=readDraft('requester-form');for(const [id,value]of Object.entries(draft.fields||{}))if($(id))$(id).value=value;if(draft.pending){$('requester-submit').textContent='Retry the same service request';$('requester-submit').disabled=requesterBusy;}if(selected&&result.requests.some(r=>r.id===selected))showRequester(selected);}catch(error){if(generation===requesterGeneration){$('requester-list').replaceChildren();$('requester-detail').replaceChildren();$('requester-submit').disabled=true;message(error.message,true);}}}
  async function showRequester(id){const generation=++requesterGeneration;try{const result=await api(opUrl('/requester/'+encodeURIComponent(id)));if(generation!==requesterGeneration||section!=='requester')return;selected=id;rememberUrl();$('requester-detail').innerHTML=`<h3>${esc(result.title)}</h3><span class="badge">${esc(result.status)}</span><p>${esc(result.description)}</p>${result.updates.map(update=>`<article><p>${esc(update.message)}</p><p class="caption">${esc(update.at)}</p></article>`).join('')||'<p>No public update yet.</p>'}<p class="caption">${esc(result.coverage)}</p>`;}catch(error){if(generation===requesterGeneration){$('requester-detail').replaceChildren();message(error.message,true);}}}
  $('requester-form').oninput=()=>{const draft=readDraft('requester-form');writeDraft('requester-form',{...draft,fields:Object.fromEntries(['requester-title','requester-description','requester-location','requester-category','requester-department'].map(id=>[id,$(id).value]))});};
  $('requester-form').onsubmit=async e=>{e.preventDefault();if(requesterBusy)return;requesterBusy=true;$('requester-submit').disabled=true;const submissionGeneration=requesterGeneration;const draft=readDraft('requester-form'),body=draft.pending||{id:crypto.randomUUID(),request_id:crypto.randomUUID(),area_id:$('requester-department').value,title:$('requester-title').value,description:$('requester-description').value,location:$('requester-location').value,category:$('requester-category').value};writeDraft('requester-form',{...draft,pending:body});try{const result=await api(opUrl('/requester'),body);writeDraft('requester-form',{});if(section!=='requester'||submissionGeneration!==requesterGeneration)return;$('requester-form').reset();selected=result.id;message('Service request saved. Follow it here without department access.');await loadRequester();}catch(error){if(section==='requester'&&submissionGeneration===requesterGeneration){message(error.message+' Your exact submission is retained.',true);$('requester-submit').textContent='Retry the same service request';}}finally{requesterBusy=false;$('requester-submit').disabled=section!=='requester'||!$('requester-department').options.length;}};
  function preferenceFields(){if(!preferencesState)return;const shared=$('preferences-scope').value==='workspace',role=$('preferences-role').value;const effective=shared?{density:'comfortable',view:'list',filter:'all',...(preferencesState.layout_defaults||{}),...(role==='all'?{}:preferencesState.role_defaults?.[role]||{})}:preferencesState.effective;$('preferences-role').disabled=!shared||!preferencesState.can_manage;$('preferences-intake').disabled=!shared||!preferencesState.can_manage;$('preferences-density').value=effective.density||'comfortable';$('preferences-view').value=effective.view||'list';$('preferences-filter').value=effective.filter||'all';}
  $('preferences-scope').onchange=preferenceFields;$('preferences-role').onchange=preferenceFields;
  async function loadPreferences(){
    if(!area)return;const scopeArea=area;
    try{const result=await api(opUrl('/preferences',{area_id:scopeArea}));if(area!==scopeArea)return;const first=preferencesArea!==scopeArea;preferencesState=result;preferencesArea=scopeArea;$('workspace-license').textContent=result.licensing.description;$('preferences-scope').querySelector('[value=workspace]').disabled=!result.can_manage;$('preferences-intake').checked=result.intake_published;preferenceFields();document.documentElement.dataset.workspaceDensity=result.effective.density;
      $('workspace-favorites').innerHTML=(result.effective.favorites||[]).map(id=>data.projects.find(project=>project.id===id)).filter(Boolean).map(project=>`<button class="button" type="button" data-favorite-project="${esc(project.id)}">${esc(project.name)}</button>`).join('');$('workspace-favorites').querySelectorAll('[data-favorite-project]').forEach(button=>button.onclick=()=>moveTo('projects',button.dataset.favoriteProject));if(first){view=result.effective.view||'list';map=view==='map';render({preserveDetail:true});}else renderFavoriteProject();
    }catch(error){preferencesState=null;$('workspace-preferences').hidden=true;}
  }
  function renderFavoriteProject(){
    $('project-favorite-toggle')?.remove();if(section!=='projects'||!selected||!preferencesState||preferencesArea!==area)return;
    const project=data.projects.find(row=>row.id===selected);if(!project)return;
    const button=document.createElement('button');button.id='project-favorite-toggle';button.className='button';const saved=(preferencesState.effective.favorites||[]).includes(project.id);button.textContent=saved?'Remove from my favorites':'Save project to my favorites';
    button.onclick=async()=>{const scopeArea=area,scopeProject=selected,draftKey='preferences:'+area,prior=readDraft(draftKey);const favorites=saved?(preferencesState.effective.favorites||[]).filter(id=>id!==project.id):[...new Set([...(preferencesState.effective.favorites||[]),project.id])];
      const body=prior.pending||{area_id:area,scope:'personal',request_id:crypto.randomUUID(),expected_version:preferencesState.personal_version,settings:{density:preferencesState.effective.density,view:preferencesState.effective.view,filter:preferencesState.effective.filter,favorites}};
      writeDraft(draftKey,{pending:body});button.disabled=true;try{await api(opUrl('/preferences'),body);writeDraft(draftKey,{});if(area!==scopeArea||selected!==scopeProject)return;await loadPreferences();renderFavoriteProject();message('Personal favorites saved.');}catch(error){if(area===scopeArea&&selected===scopeProject){button.disabled=false;message(error.message+' Retry keeps the same saved settings.',true);}}
    };$('detail').prepend(button);
  }
  $('preferences-form').onsubmit=async e=>{
    e.preventDefault();if(!preferencesState||preferencesArea!==area)return;const scope=$('preferences-scope').value,role=$('preferences-role').value,settings={density:$('preferences-density').value,view:$('preferences-view').value,filter:$('preferences-filter').value,...(scope==='personal'?{favorites:preferencesState.effective.favorites||[]}:{})};
    const scopeArea=area,draftKey='preferences:'+scopeArea,draft=readDraft(draftKey),body=draft.pending||{area_id:area,scope,request_id:crypto.randomUUID(),expected_version:scope==='personal'?preferencesState.personal_version:preferencesState.shared_version,settings:scope==='workspace'&&role!=='all'?(preferencesState.layout_defaults||{}):settings,...(scope==='workspace'?{intake_published:$('preferences-intake').checked,roles:{...(preferencesState.role_defaults||{}),...(role==='all'?{}:{[role]:settings})}}:{})};
    writeDraft(draftKey,{pending:body});try{const result=await api(opUrl('/preferences'),body);writeDraft(draftKey,{});if(area!==scopeArea)return;preferencesState=result;document.documentElement.dataset.workspaceDensity=result.effective.density;view=result.effective.view||'list';map=view==='map';await loadPreferences();render();message('Layout settings saved. Memberships and billing are unchanged.');}catch(error){if(area===scopeArea)message(error.message+' Exact settings are retained for retry.',true);}
  };
  $('operations-plan-open').onclick=()=>moveTo('contractors');
  async function loadPeople(){const scopeArea=area;const generation=++operationsGeneration;$('operations-members').innerHTML=data.members.map(member=>`<p>${esc(member.name)}</p>`).join('')||'<p>No editable workspace members in this projection.</p>';try{const result=await api(opUrl('/planning',{area_id:scopeArea}));if(area!==scopeArea||section!=='people'||generation!==operationsGeneration)return;const contractors=result.items.filter(row=>row.kind==='contractor');$('operations-contractors').innerHTML=contractors.map(row=>`<article class="planning-record"><h3>${esc(row.title)}</h3><p>${esc(row.status)}</p><button class="button" data-quality="${esc(row.id)}">Review contractor quality</button></article>`).join('')||'<p>No external contacts recorded.</p>';$('operations-contractors').querySelectorAll('[data-quality]').forEach(button=>button.onclick=()=>showQuality(button.dataset.quality));}catch(error){if(generation===operationsGeneration)$('operations-contractors').textContent=error.message;}}
  async function showQuality(id){const scopeArea=area;try{const [quality,ops]=await Promise.all([api(opUrl('/operations/contractors/'+id+'/quality',{area_id:area})),api(opUrl('/operations',{area_id:area}))]);if(area!==scopeArea||section!=='people')return;const host=$('operations-quality');host.hidden=false;host.innerHTML=`<h3>Contractor quality: ${esc(quality.quality_label)}</h3><p class="caption">${quality.review_count} current authorized reviews · separate from checklist completion</p><div>${quality.reviews.map(review=>`<article class="planning-record"><strong>${esc(review.task_title)}</strong><p>${esc(review.note||'')}</p><p class="caption">${esc(review.reviewed_at)}</p></article>`).join('')}</div><form id="quality-form" class="stack"><label>Supporting job<select name="task_id" required>${ops.items.map(task=>`<option value="${esc(task.id)}">${esc(task.title)}</option>`).join('')}</select></label><div class="field-pair">${['workmanship','timeliness','communication','documentation'].map(d=>`<label>${d[0].toUpperCase()+d.slice(1)}<input name="${d}" type="number" min="0" max="4" step="1" value="0" required></label>`).join('')}</div><label>Review comments<textarea name="note" maxlength="2000"></textarea></label><button class="button" type="submit">Save manager review</button></form><p class="caption">${esc(quality.coverage)}</p>`;$('quality-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),taskId=f.get('task_id'),prior=quality.reviews.find(row=>row.task_id===taskId);sendOps({action:'contractor.review',task_id:taskId,contractor_id:id,expected_version:prior?.version||0,request_id:crypto.randomUUID(),note:f.get('note'),...Object.fromEntries(['workmanship','timeliness','communication','documentation'].map(d=>[d,Number(f.get(d))]))},scopeArea+':quality:'+id+':'+taskId,()=>showQuality(id));};}catch(error){$('operations-quality').hidden=false;$('operations-quality').textContent=error.status===404?'Contractor evaluations are restricted to current workspace managers.':error.message;}}
  document.addEventListener('enterprise:render',()=>{
    syncOpsContext();
    if(!area&&data.features?.requester&&section==='home')section='requester';
    for(const [name,flag]of[['roll_call','roll_call'],['buildings','resources'],['calendar','resources'],['people','operations'],['assets','resources'],['workflows','workflow'],['requester','requester']]){const id=name==='roll_call'?'roll-call-nav':name+'-nav';$(id).hidden=!data.features?.[flag];}
    $('campus-search').hidden=section!=='home'||!data.features?.operations;if(section==='home'&&$('campus-search').parentElement!==$('campus-home'))$('campus-home').prepend($('campus-search'));$('workspace-preferences').hidden=!data.features?.operations||!area;
    for(const [id,name]of[['operations-people','people'],['operations-workflows','workflows'],['requester-portal','requester']])$(id).hidden=section!==name;
    if(customSections.includes(section)){$('work').hidden=true;$('campus-home').hidden=true;$('ask').hidden=true;$('contractors').hidden=true;$('create-request').hidden=true;$('create-project').hidden=true;const labels={roll_call:'Roll Call',buildings:'Buildings',calendar:'Calendar',people:'People & contractors',assets:'Assets',workflows:'Workflows',requester:'My service requests'};$('heading').textContent=labels[section];$('breadcrumb').textContent=labels[section];}
    if(data.features?.operations&&area&&preferencesArea!==area)loadPreferences();
    if(section==='people'&&data.features?.operations)loadPeople();
    if(section==='requester'&&data.features?.requester)loadRequester();
    if(section==='workflows')$('operations-workflow-projects').innerHTML=data.projects.map(project=>`<article><h3>${esc(project.name)}</h3><a class="button primary" href="${esc(transport.href(urls.workflowWorkspace+'?tenant='+encodeURIComponent(tenantSlug)+'&area_id='+encodeURIComponent(area)+'&project_id='+encodeURIComponent(project.id)))}">Open complete workflow workspace</a></article>`).join('')||'<p class="ops-empty">Choose a workspace with an authorized project first.</p>';
    renderFavoriteProject();rememberUrl();
  });
